/**
 * Converts a Pipedream timer trigger into a Bidspoke schedule (#1952), or
 * refuses it by name. Its committed fixture is every timer in the 2026-09-30
 * export (fixtures/pipedream-timers.json, regenerated by
 * scripts/porting/timer-fixture.ts), and its test runs over all of them.
 *
 * What a Pipedream timer is, MEASURED on 2026-10-16 rather than assumed (L34):
 * - Shape: `{ type: 'timer', disabled?, props: { cron | interval_seconds, timezone } }`.
 *   The export's 77 timers carry exactly those prop keys: 67 crons, 10
 *   intervals, 4 disabled, zones America/New_York, UTC and Etc/UTC.
 * - Pipedream's component source (PipedreamHQ/pipedream at f71f4a16) does NOT
 *   hold the scheduler: packages/sdk/src/shared/component.ts types a timer as
 *   `{ cron: string }` or `{ intervalSeconds: number }` and nothing in the
 *   repository parses a cron, and the trigger docs say nothing of weekday
 *   numbering or daylight saving. So the numbering is measured from the export:
 *   - Pipedream accepted both `0` (`30 11 * * 0`, `45 14 * * 0`) and `7`
 *     (`*\/5 8-20 * * 1-7`) in the weekday field. A Quartz style 1 to 7 field
 *     refuses 0 and a 0 to 6 field refuses 7, so the field is 0 to 7, the Vixie
 *     numbering in which 0 and 7 are both Sunday and 1 is Monday.
 *   - The Trustpilot Alert Manager Email workflow (p_A2C13eG, `15 10 * * 5`)
 *     computes its window as "Last Friday" by subtracting 7 days from the run's
 *     own date, so its author saw 5 fire on Fridays: Vixie, not Quartz, where 5
 *     is Thursday.
 *   That is the evidence; nothing in Pipedream's own code confirms it. The
 *   independent check is a weekly workflow's run history in the Pipedream UI
 *   (Clear Shame Leaderboard, p_ljCmJ7d, `0 6 * * 1`, should show Mondays).
 * - Daylight saving is UNMEASURED: no source and no doc says what Pipedream does
 *   with a New York wall time the spring change skips or the autumn change
 *   repeats. Two exported crons hit one: RML - CRON - Phone Line Data Store
 *   (p_q6CyvJN, `4 2 * * *`) and Booking Monitor (p_mkCPM7J,
 *   `0 21,23,1,3,5 * * *`). Bidspoke fires each such slot once (fires.ts) and
 *   the converter flags those crons with a `daylight_saving_wall_time` note.
 * - `0/30`, a start with a step and no range, is read as 0 and 30, its meaning
 *   in the parsers that accept the form (Quartz, and cron-parser on npm). That
 *   Pipedream reads it so is inferred, not measured.
 *
 * The output: the weekday field is rewritten in NAMES (MON-FRI, never 1-5) and
 * the other four fields are kept as written; Etc/UTC is read as UTC; the
 * settings are the defaults by period (schedule.ts). A disabled timer, an
 * unknown prop, a zone outside SCHEDULE_ZONES and anything the cron grammar
 * refuses are refused by name, never dropped (#1698 1.6).
 */
import { isScheduleZone, type ScheduleZone } from '@bidspoke/buyer-profile'
import { namedWeekdayField, parseCron } from './cron'
import { intervalProblem } from './fires'
import { problem, type ScheduleProblem } from './problems'
import { scheduleDefaults, type ScheduleConfig } from './schedule'

export type ConversionNoteCode = 'timezone_read_as_utc' | 'weekdays_named' | 'daylight_saving_wall_time'

export interface ConversionNote {
  code: ConversionNoteCode
  message: string
}

export type ConvertResult =
  | { ok: true; schedule: ScheduleConfig; notes: ConversionNote[] }
  | { ok: false; problem: ScheduleProblem }

const KNOWN_PROPS = new Set(['cron', 'interval_seconds', 'timezone'])
/** Pipedream zone names read as a schedule zone. */
const ZONE_ALIASES: Readonly<Record<string, ScheduleZone>> = { 'Etc/UTC': 'UTC' }
/** The local hours a daylight saving change skips (2) or repeats (1) in the US zones. */
const CHANGE_HOURS = new Set([1, 2])

const refuse = (p: ScheduleProblem): ConvertResult => ({ ok: false, problem: p })

export function convertPipedreamTimer(trigger: unknown): ConvertResult {
  const t = trigger as { type?: unknown; disabled?: unknown; props?: unknown } | null
  if (t === null || typeof t !== 'object' || t.type !== 'timer' || t.props === null || typeof t.props !== 'object' || Array.isArray(t.props)) {
    return refuse(problem('not_a_timer', 'this is not a Pipedream timer trigger with props'))
  }
  if (t.disabled === true) {
    return refuse(problem('timer_disabled', 'the timer is disabled on Pipedream, so converting it would start a schedule that was off'))
  }
  const props = t.props as Record<string, unknown>
  const unknown = Object.keys(props).filter((k) => !KNOWN_PROPS.has(k))
  if (unknown.length > 0) {
    return refuse(problem('timer_props_unknown', `the timer carries ${unknown.join(', ')}, which the converter does not know; nothing is dropped, so it is refused`))
  }

  const notes: ConversionNote[] = []
  const rawZone = props.timezone
  const zone = typeof rawZone === 'string' ? (ZONE_ALIASES[rawZone] ?? rawZone) : rawZone
  if (!isScheduleZone(zone)) {
    return refuse(problem('timezone_unsupported', `the timer's zone ${String(rawZone)} is not one a schedule may fire in (America/New_York, America/Los_Angeles, UTC)`))
  }
  if (zone !== rawZone) notes.push({ code: 'timezone_read_as_utc', message: `the zone ${String(rawZone)} is read as UTC` })

  const hasCron = props.cron !== undefined
  const hasInterval = props.interval_seconds !== undefined
  if (!hasCron && !hasInterval) return refuse(problem('schedule_needs_cron_or_interval', 'the timer has neither a cron nor an interval'))
  if (hasCron && hasInterval) return refuse(problem('schedule_has_cron_and_interval', 'the timer has both a cron and an interval'))

  if (hasInterval) {
    const p = intervalProblem(props.interval_seconds)
    if (p) return refuse(p)
    const interval_seconds = props.interval_seconds as number
    return { ok: true, schedule: { interval_seconds, timezone: zone, ...scheduleDefaults({ interval_seconds }, zone) }, notes }
  }

  const parsed = parseCron(props.cron as string, 'pipedream')
  if (!parsed.ok) return refuse(parsed.problem)
  const [min, hour, dom, month, dow] = parsed.fields
  const named = dow === '*' ? '*' : namedWeekdayField(parsed.spec.weekdays)
  if (dow !== '*') notes.push({ code: 'weekdays_named', message: `the weekdays ${dow} are written ${named} (Pipedream's numbering: 0 and 7 are Sunday, 1 is Monday)` })
  if (zone !== 'UTC' && parsed.spec.hours.some((h) => CHANGE_HOURS.has(h))) {
    notes.push({ code: 'daylight_saving_wall_time', message: `the cron fires at a ${zone} hour a daylight saving change skips or repeats; Bidspoke fires that slot once, and what Pipedream did there is unmeasured` })
  }
  const cron = `${min} ${hour} ${dom} ${month} ${named}`
  return { ok: true, schedule: { cron, timezone: zone, ...scheduleDefaults({ cron }, zone) }, notes }
}
